// The eval datasets: three FROZEN files under tests/fixtures/evals/,
// GENERATED by this file, never hand-edited. The datasets are committed before any
// run — vitest or real — and every run reads them and verifies their hash first:
// a changed dataset means a new dataset, never a quiet rewrite of old results.
// Run `MKMN_GENERATE_FIXTURES=1 pnpm exec vitest run tests/eval-datasets.test.ts`
// to (re)write them.
//
//  - identity.json: five questions (English and Arabic) that make a base model name
//    itself or its maker wrongly, plus the voice and after-compaction variants.
//  - long-conversations.json: ten scripted conversations of 40-120 turns (English,
//    Arabic and mixed), the fact said early, the question asked late.
//  - knowledge.json: questions over the knowledge fixtures (tests/fixtures/knowledge/),
//    including the scanned file's recognized words (the scan's own text layer is empty
//    by design; the frozen words here stand for what Windows.Media.Ocr reads off it).
//
// The generated long conversations are deterministic: the filler turns cycle fixed
// template pools by turn index, so the same dataset comes out of every generation.
import { describe, expect, it } from "vitest";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { datasetHashOf, type EvalCase } from "../src/core/harness/evals";

const HERE = join(fileURLToPath(import.meta.url), "..");
const OUT = join(HERE, "fixtures", "evals");
const GENERATE = process.env.MKMN_GENERATE_FIXTURES === "1";

