// ---------------------------------------------------------------- generation and verification

interface DatasetFile { name: string; id: string; description: string; cases: EvalCase[]; ocr?: { file: string; pages: string[] }[] }

const DATASETS: DatasetFile[] = [
  { name: "identity.json", id: "identity", description: "Five questions EN+AR that make a base model name itself or its maker wrongly, plus the voice and after-compaction variants.", cases: identityCases },
  { name: "long-conversations.json", id: "long-conversations", description: "Ten scripted conversations of 40-120 turns (EN, AR and mixed); the fact rides turn 0, the question comes last.", cases: longConversationCases() },
  { name: "knowledge.json", id: "knowledge", description: "Questions over the knowledge fixtures (tests/fixtures/knowledge/), including the scanned file's recognized words and the cross-language cases.", cases: knowledgeCases, ocr: OCR_PAGES },
];

const manifestOf = (written: { file: string; dataset: EvalDataset }[]) => ({
  note: "Generated by tests/eval-datasets.test.ts with MKMN_GENERATE_FIXTURES=1; never hand-edited. Each dataset's hash covers its cases; the eval runs verify it before scoring.",
  datasets: written.map(({ file, dataset }) => ({ file, id: dataset.id, hash: dataset.hash, cases: dataset.cases.length })),
});

describe("the eval datasets", () => {
  const written: { file: string; dataset: EvalDataset }[] = [];

  it("generates the frozen datasets when MKMN_GENERATE_FIXTURES=1", () => {
    if (!GENERATE) return; // the verification below always runs against the committed files
    mkdirSync(OUT, { recursive: true });
    for (const d of DATASETS) {
      const dataset: EvalDataset = { id: d.id, description: d.description, hash: datasetHashOf(d.cases), ...(d.ocr ? { ocr: d.ocr } : {}), cases: d.cases };
      writeFileSync(join(OUT, d.name), JSON.stringify(dataset, null, 2) + "\n", "utf8");
      written.push({ file: d.name, dataset });
    }
    writeFileSync(join(OUT, "MANIFEST.json"), JSON.stringify(manifestOf(written), null, 2) + "\n", "utf8");
    expect(written.length).toBe(DATASETS.length);
  });

  it("every dataset exists and its committed hash matches its cases", () => {
    for (const d of DATASETS) {
      const file = join(OUT, d.name);
      expect(existsSync(file), d.name).toBe(true);
      const parsed = JSON.parse(readFileSync(file, "utf8")) as EvalDataset;
      expect(parsed.hash, d.name).toBe(datasetHashOf(parsed.cases));
      expect(parsed.id).toBe(d.id);
    }
  });

  it("identity: five questions EN+AR, with voice and after-compaction variants", () => {
    const parsed = JSON.parse(readFileSync(join(OUT, "identity.json"), "utf8")) as EvalDataset;
    const base = parsed.cases.filter((c) => !c.voice && !c.afterCompaction);
    expect(base.length).toBe(5);
    expect(base.some((c) => c.lang === "ar")).toBe(true);
    expect(base.some((c) => c.lang === "en")).toBe(true);
    expect(parsed.cases.some((c) => c.voice)).toBe(true);
    expect(parsed.cases.some((c) => c.afterCompaction)).toBe(true);
    for (const c of parsed.cases) expect(c.wrongReply).toBeTruthy();
  });

  it("long conversations: ten of them, 40-120 turns, EN+AR, the fact early and the question last", () => {
    const parsed = JSON.parse(readFileSync(join(OUT, "long-conversations.json"), "utf8")) as EvalDataset;
    expect(parsed.cases.length).toBeGreaterThanOrEqual(10);
    for (const c of parsed.cases) {
      expect(c.turns!.length).toBeGreaterThanOrEqual(40);
      expect(c.turns!.length).toBeLessThanOrEqual(120);
      expect(c.lang === "ar" || c.lang === "en").toBe(true);
      expect(c.factTurn!).toBeLessThan(5);
      // the fact rides its turn; the question is the last turn
      expect(c.turns![c.factTurn!].text).toContain(c.fact);
      expect(c.turns![c.turns!.length - 1].text).toBe(c.question);
      expect(c.turns![c.turns!.length - 1].role).toBe("user");
    }
    // EN and Arabic both present
    expect(new Set(parsed.cases.map((c) => c.lang)).size).toBe(2);
  });

  it("knowledge: thirty or more questions over the fixtures, scanned included, cross-language included", () => {
    const parsed = JSON.parse(readFileSync(join(OUT, "knowledge.json"), "utf8")) as EvalDataset;
    expect(parsed.cases.length).toBeGreaterThanOrEqual(30);
    for (const c of parsed.cases) {
      expect(c.file).toBeTruthy();
      expect(c.fact).toBeTruthy();
      expect(c.question).toBeTruthy();
    }
    const files = new Set(parsed.cases.map((c) => c.file!));
    for (const f of ["handbook-en.pdf", "dalil-ar.pdf", "scanned-notices.pdf", "staff-handbook.docx", "equipment.xlsx", "renovation-plan.pptx"]) expect(files.has(f), f).toBe(true);
    const cross = parsed.cases.filter((c) => c.crossLanguage);
    expect(cross.length).toBeGreaterThanOrEqual(6);
    for (const c of cross) expect(c.searchWords).toBeTruthy();
    // the scanned file's frozen OCR words are here
    expect(parsed.ocr?.length).toBe(1);
    expect(parsed.ocr![0].pages.length).toBe(3);
  });
});
